1	export type Cell = [number, number];
2	
3	const NEIGHBOR_OFFSETS: Cell[] = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [0, -1], [0, 1],
6	  [1, -1], [1, 0], [1, 1],
7	];
8	
9	function neighbors([x, y]: Cell): Cell[] {
10	  return NEIGHBOR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
11	}
12	
13	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
14	  return x === otherX && y === otherY;
15	}
16	
17	function isAlive(cell: Cell, liveCells: Cell[]): boolean {
18	  return liveCells.some((other) => isSameCell(cell, other));
19	}
20	
21	function liveNeighborCount(cell: Cell, liveCells: Cell[]): number {
22	  return neighbors(cell).filter((neighbor) => isAlive(neighbor, liveCells)).length;
23	}
24	
25	/**
26	 * A birth needs 3 live neighbours, so only live cells and the cells touching
27	 * them can be alive next generation.
28	 */
29	function cellsThatCouldBeAlive(liveCells: Cell[]): Cell[] {
30	  const found: Cell[] = [];
31	  for (const cell of liveCells) {
32	    for (const candidate of [cell, ...neighbors(cell)]) {
33	      if (!isAlive(candidate, found)) found.push(candidate);
34	    }
35	  }
36	  return found;
37	}
38	
39	function survives(neighborCount: number): boolean {
40	  return neighborCount === 2 || neighborCount === 3;
41	}
42	
43	function isBorn(neighborCount: number): boolean {
44	  return neighborCount === 3;
45	}
46	
47	export function nextGeneration(liveCells: Cell[]): Cell[] {
48	  return cellsThatCouldBeAlive(liveCells).filter((cell) => {
49	    const neighborCount = liveNeighborCount(cell, liveCells);
50	    return isAlive(cell, liveCells) ? survives(neighborCount) : isBorn(neighborCount);
51	  });
52	}
